const fields={arrival:['Dolazak i lokacija','Arrival and location','Anreise und Lage'],parking:['Parking','Parking','Parkplatz'],checkIn:['Preuzimanje ključa / prijava','Keys and check-in','Schlüssel und Check-in'],wifiName:['Wi-Fi naziv mreže','Wi-Fi network name','WLAN-Netzwerkname'],wifiPassword:['Wi-Fi lozinka','Wi-Fi password','WLAN-Passwort'],houseRules:['Kućni red','House rules','Hausregeln'],contact:['Kontakt domaćina / pomoć','Host contact / help','Kontakt / Hilfe']};
const emptyGuide=()=>({revision:0,texts:Object.fromEntries(['hr','en','de'].map(l=>[l,Object.fromEntries(Object.keys(fields).map(k=>[k,'']))]))});
export function guideContent(data,lang,esc){const n={hr:0,en:1,de:2}[lang]||0;return Object.entries(fields).map(([k,labels])=>{const value=data.texts?.[lang]?.[k]||data.texts?.hr?.[k];return `<section class="guest-guide-block"><h2>${labels[n]}</h2><p class="preserve-lines">${esc(value||['Podatak će dodati domaćin.','The host will add this information.','Diese Information ergänzt der Gastgeber.'][n])}</p></section>`}).join('')}
export function createHostTools({esc,getSite,getBookings,getInquiries,isDemo,api,render}){
 let calendar=null,guide=null,links=[],notice='',issuedLink='',issuedExport='',preview=false,dirty=false;
 const input=(label,name,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const apartmentOptions=()=>getSite().apartments.map(a=>`<option value="${a.slug}">${esc(a.name)}</option>`).join('');
 function calendarPage(){return `<div class="admin-card"><h2>Airbnb i Booking.com kalendari.</h2><p>Uvezite izvorne iCal poveznice za svaki apartman. Uvoz osvježava samo zauzete datume, bez imena gostiju i poruka.</p><p class="section-note">Automatska provjera pokreće se pri otvaranju kalendara na stranici, najviše jednom u 15 minuta po vezi (do tri veze po zahtjevu). Bez posjeta nema pozadinskog osvježavanja. Ručna provjera dostupna je ispod. Promjene na drugim servisima mogu kasniti.</p><button class="btn outline" id="load-calendar-connections">${calendar?'Osvježi popis':'Učitaj veze'} ↻</button>${isDemo()?'<p class="section-note">Ogledni način: stvarna povezivanja i sinkronizacija nisu aktivni.</p>':''}<p class="admin-notice" id="host-tools-status" role="status">${esc(notice)}</p>${calendar?`<form id="feed-form" class="form-grid"><label class="field">Apartman<select name="apartment">${apartmentOptions()}</select></label>${input('Izvozna iCal poveznica Airbnb / Booking.com','url','','type="url" required maxlength="3000" autocomplete="off"')}<button class="btn full">Dodaj privatnu vezu +</button></form><div class="booking-list">${calendar.feeds.length?calendar.feeds.map(f=>`<article><div><strong>${esc(getSite().apartments.find(a=>a.slug===f.apartment)?.name||f.apartment)} · ${esc(f.provider)}</strong><p>Status: ${{ready:'Sinkronizirano',error:'Provjera nije uspjela — zadržano prethodno zauzeće',pending:'Čeka prvu provjeru',syncing:'Provjera u tijeku'}[f.state]||'Čeka provjeru'}</p><p>${f.count} razdoblja · Zadnja uspješna provjera: ${esc(f.lastSuccess||'nije provedena')}</p></div><div class="inbox-actions"><button class="btn outline" data-sync-feed="${f.id}">Sinkroniziraj</button><button class="danger-button" data-remove-feed="${f.id}">Ukloni vezu i uvezene datume</button></div></article>`).join(''):'<p>Nema povezanih kalendara.</p>'}</div><h3>Izvoz iz Meleh kalendara</h3><p class="section-note">Poveznicu uvezite u Airbnb ili Booking.com. Izvoze se samo ručno unesena zauzeća iz Meleha, bez privatnih bilješki i bez ponovno uvezenih datuma. Poveznica je tajna; možete je opozvati.</p><form id="calendar-export-form" class="form-grid"><label class="field">Apartman<select name="apartment">${apartmentOptions()}</select></label><button class="btn">Stvori izvoznu poveznicu</button></form>${issuedExport?`<label class="field">Kopirajte novu privatnu iCal poveznicu (prikazuje se samo sada)<input readonly value="${esc(issuedExport)}"></label>`:''}<div class="booking-list">${calendar.exports.map(e=>`<article><span>${esc(getSite().apartments.find(a=>a.slug===e.apartment)?.name||e.apartment)} · ${esc(e.createdAt?.slice(0,10))}</span><button class="danger-button" data-revoke-export="${e.id}">Opozovi izvoz</button></article>`).join('')}</div>`:''}</div>`}
 const sources=()=>[...getBookings().map(b=>({...b,type:'booking'})),...getInquiries().filter(i=>i.status==='confirmed').map(i=>({...i,type:'inquiry'}))].filter(b=>b.departure>=new Date().toLocaleDateString('en-CA'));
 function guidePage(){return `<div class="admin-card"><h2>Privatni vodič za potvrđene goste.</h2><p>Unesite upute koje gost treba nakon potvrde boravka. Ovi podaci nisu dio javnog sadržaja stranice.</p><button class="btn outline" id="load-private-guide">${guide?'Ponovno učitaj vodič':'Učitaj privatni vodič'} ↻</button><p id="host-tools-status" class="admin-notice" role="status">${esc(notice)}</p>${guide?`<form id="private-guide-form"><div class="day-tabs">${['hr','en','de'].map(l=>`<a href="#guide-${l}">${l.toUpperCase()}</a>`).join('')}</div>${['hr','en','de'].map(l=>`<fieldset id="guide-${l}" class="editorial-row"><legend>${l.toUpperCase()}</legend>${Object.entries(fields).map(([k,label])=>`<label class="field">${label[0]}<textarea name="${l}_${k}" maxlength="3000" rows="2" autocomplete="off">${esc(guide.texts[l]?.[k]||'')}</textarea></label>`).join('')}</fieldset>`).join('')}<button class="btn">${isDemo()?'Spremi ogledni vodič':'Spremi privatne upute'} ↗</button></form><h3 style="margin-top:35px">Poveznice za goste</h3><p class="section-note">Prvo spremite privatne upute. Poveznica vrijedi do dana nakon odlaska i može se opozvati. Brisanje zauzeća ili otkazivanje potvrđenog upita također ukida pristup. Dijelite je samo odgovarajućem gostu.</p>${sources().length?`<form id="guest-link-form" class="form-grid"><label class="field">Potvrđeni boravak<select name="source">${sources().map(b=>`<option value="${b.type}:${esc(b.id)}">${esc(getSite().apartments.find(a=>a.slug===b.apartment)?.name||b.apartment)} · ${b.arrival} → ${b.departure} (${b.type==='booking'?'zauzeće':'potvrđeni upit'})${b.name?' · '+esc(b.name):''}</option>`).join('')}</select></label><button class="btn">${isDemo()?'Prikaži ogledni vodič':'Stvori privatnu poveznicu'}</button></form>`:'<p>Prvo unesite potvrđeno zauzeće ili označite upit kao „Potvrđeno”.</p>'}${issuedLink?`<label class="field">Nova privatna poveznica (kopirajte sada)<input readonly value="${esc(issuedLink)}"></label><p class="section-note">Poveznica se zbog privatnosti neće ponovno prikazati nakon osvježavanja.</p>`:''}${preview?`<details open><summary>Ogledni vodič · bez javne poveznice</summary>${guideContent(guide,'hr',esc)}</details>`:''}<div class="booking-list">${links.map(l=>`<article><div><strong>${esc(getSite().apartments.find(a=>a.slug===l.apartment)?.name||l.apartment)}</strong><p>${l.arrival} → ${l.departure}</p><small>Vrijedi do ${esc(l.expiresAt)}</small></div><button class="danger-button" data-revoke-guest="${l.id}">Opozovi pristup</button></article>`).join('')}</div>`:''}</div>`}
 async function action(fn){const node=document.querySelector('.admin-shell');node.inert=true;try{await fn();notice='Spremljeno / osvježeno.';render()}catch(e){notice=e.message;const el=document.querySelector('#host-tools-status');if(el)el.textContent=notice}finally{const el=document.querySelector('.admin-shell');if(el)el.inert=false}}
 function bind(){const loadCalendar=document.querySelector('#load-calendar-connections');if(loadCalendar)loadCalendar.onclick=()=>action(async()=>calendar=isDemo()?{feeds:[],exports:[]}:await api('calendar-feeds'));
 const feed=document.querySelector('#feed-form');if(feed)feed.onsubmit=e=>{e.preventDefault();action(async()=>{if(isDemo())throw new Error('Stvarnu iCal vezu dodajte nakon administratorske prijave.');await api('calendar-feeds',{method:'POST',body:Object.fromEntries(new FormData(feed))});calendar=await api('calendar-feeds')})};
 document.querySelectorAll('[data-sync-feed]').forEach(b=>b.onclick=()=>action(async()=>{calendar=await api('calendar-sync',{method:'POST',body:{id:b.dataset.syncFeed}})}));
 document.querySelectorAll('[data-remove-feed]').forEach(b=>b.onclick=()=>action(async()=>{await api('calendar-feeds',{method:'DELETE',body:{id:b.dataset.removeFeed}});calendar=await api('calendar-feeds')}));
 const exp=document.querySelector('#calendar-export-form');if(exp)exp.onsubmit=e=>{e.preventDefault();action(async()=>{if(isDemo())throw new Error('Stvarni izvoz kalendara dostupan je samo administratoru.');const result=await api('calendar-export',{method:'POST',body:{apartment:exp.apartment.value}});issuedExport=location.origin+'/api/calendar.ics?token='+result.token;calendar=await api('calendar-feeds')})};
 document.querySelectorAll('[data-revoke-export]').forEach(b=>b.onclick=()=>action(async()=>{await api('calendar-export',{method:'DELETE',body:{id:b.dataset.revokeExport}});issuedExport='';calendar=await api('calendar-feeds')}));
 const loadGuide=document.querySelector('#load-private-guide');if(loadGuide)loadGuide.onclick=()=>action(async()=>{if(isDemo()){guide=guide||emptyGuide();links=[]}else{const result=await api('guest-guide');guide=result.settings;links=result.links}});
 const form=document.querySelector('#private-guide-form');if(form){form.oninput=()=>{dirty=true;const values=Object.fromEntries(new FormData(form));for(const l of ['hr','en','de'])for(const k of Object.keys(fields))guide.texts[l][k]=values[l+'_'+k]||''};form.onsubmit=e=>{e.preventDefault();action(async()=>{const values=Object.fromEntries(new FormData(form)),next={revision:guide.revision,texts:Object.fromEntries(['hr','en','de'].map(l=>[l,Object.fromEntries(Object.keys(fields).map(k=>[k,values[l+'_'+k]||'']))]))};if(isDemo())guide=next;else{await api('guest-guide',{method:'PUT',body:next});const result=await api('guest-guide');guide=result.settings;links=result.links}dirty=false})}};
 const make=document.querySelector('#guest-link-form');if(make)make.onsubmit=e=>{e.preventDefault();action(async()=>{if(isDemo()){preview=true;return}if(dirty)throw new Error('Najprije spremite privatne upute.');const [sourceType,sourceId]=make.source.value.split(':'),result=await api('guest-links',{method:'POST',body:{sourceType,sourceId}});issuedLink=location.origin+'/gost/#'+result.token;links=(await api('guest-guide')).links})};
 document.querySelectorAll('[data-revoke-guest]').forEach(b=>b.onclick=()=>action(async()=>{await api('guest-links',{method:'DELETE',body:{id:b.dataset.revokeGuest}});issuedLink='';links=(await api('guest-guide')).links}));
 }
 function reset(){calendar=null;guide=null;links=[];notice='';issuedLink='';issuedExport='';preview=false;dirty=false}
 return {calendarPage,guidePage,bind,reset};
}
export function createGuestView({t,esc,getLang}){
 let data=null,error='',busy=false,loadedToken='';
 function markup(){if(location.hash.slice(1)!==loadedToken){data=null;error=''}return `<section class="page-head"><div class="wrap"><span class="eyebrow">MELEH · ${t('ZA NAŠE GOSTE','FOR OUR GUESTS','FÜR UNSERE GÄSTE')}</span><h1>${t('Dobro došli.','Welcome.','Willkommen.')}</h1><p>${t('Vaš privatni vodič za boravak.','Your private stay guide.','Ihr privater Aufenthaltsführer.')}</p></div></section><section class="section"><div class="wrap guest-content"><div id="guest-content" aria-live="polite">${content()}</div></div></section>`}
 function content(){return error?`<p role="alert">${t('Vodič nije dostupan. Provjerite privatnu poveznicu s domaćinom; možda je istekla ili opozvana.','The guide is unavailable. Check your private link with the host; it may have expired or been revoked.','Der Reiseführer ist nicht verfügbar. Prüfen Sie den privaten Link mit dem Gastgeber; er kann abgelaufen oder widerrufen sein.')}</p>`:data?`<h2>${esc(data.apartment)}</h2><p>${data.arrival} → ${data.departure}</p>${data.mapsUrl?`<a class="btn outline" href="${esc(data.mapsUrl)}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a>`:''}${guideContent(data,getLang(),esc)}<p class="section-note">${t('Poveznicu čuvajte za sebe. Pristup istječe nakon boravka.','Keep this link private. Access expires after your stay.','Bewahren Sie diesen Link privat auf. Der Zugang endet nach dem Aufenthalt.')}</p><a class="text-link" href="/plan-dana/">${t('Vaš dan u Crikvenici','Your day in Crikvenica','Ihr Tag in Crikvenica')} ↗</a>`:`<p>${t('Otvaranje vodiča…','Opening your guide…','Ihr Reiseführer wird geöffnet…')}</p>`}
 async function bind(){const el=document.querySelector('#guest-content');if(!el)return;const token=location.hash.slice(1);if(token===loadedToken&&(data||error)){el.innerHTML=content();return}if(busy)return;busy=true;data=null;error='';loadedToken=token;try{if(!/^[a-f0-9]{64}$/.test(token))throw new Error();const r=await fetch('/api/guest-guide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token}),cache:'no-store',referrerPolicy:'no-referrer'});if(!r.ok)throw new Error();const result=await r.json();if(location.hash.slice(1)===token)data=result}catch{error=true}finally{busy=false;const target=document.querySelector('#guest-content');if(location.hash.slice(1)!==token){bind();return}if(target)target.innerHTML=content()}}
 return {markup,bind};
}
